// Spec is one playable specialisation. Spec is the spec key the whole site
// keys on, for example "warrior-fury".
type Spec struct {
	Spec          string `json:"spec"`
	ClassSlug     string `json:"class_slug"`
	SpecSlug      string `json:"spec_slug"`
	Name          string `json:"name"`
	Role          string `json:"role"`
	TreeIndex     int    `json:"tree_index"`
	ReferenceStat string `json:"reference_stat"`
	// WeightStats are the stats that actually move this spec's damage or
	// healing - the closed list /sim/weights offers, so a physical spec
	// is never asked about spirit and a caster never sees unexplained
	// zeros for expertise. ReferenceStat is always one of them.
	WeightStats []string `json:"weight_stats"`
	// Icon is the spec's icon from the active client: its tree's TalentTab
	// icon, or its form spell's (Feral, Feral Bear). A lowercase file name
	// with no extension, served under /data/<build>/icons/.
	Icon string `json:"icon"`
	// FullName is the spec as a player names it in full: "Fury Warrior",
	// "Feral Druid (Bear)". Read it; never compose Name and the class.
	FullName string `json:"full_name"`
}

